import type { CallParticipantCandidate } from "./call_participant_picker.ts";

export interface CallPromotionApi {
  get<T>(path: string): Promise<T>;
  post<T>(path: string, body: unknown): Promise<T>;
}

export interface CallPromotionResult {
  chatId: number;
  conferenceId: string;
  inviteUserIds: number[];
}

/**
 * Move a connected direct call to the SFU.
 * A two-person handoff reuses the existing dialog; a group is created only when extra people were selected.
 * The caller must join the returned room before sending `inviteUserIds` to the conference invite endpoint.
 */
export async function promoteDirectCallToConference(deps: {
  api: CallPromotionApi;
  selfId: number;
  peer: { id: number; name: string };
  selected: CallParticipantCandidate[];
  video: boolean;
  locale: string;
}): Promise<CallPromotionResult> {
  if (!Number.isSafeInteger(deps.peer.id) || deps.peer.id <= 0 || deps.peer.id === deps.selfId) {
    throw new Error("peer required");
  }
  const selectedById = new Map<number, CallParticipantCandidate>();
  for (const row of deps.selected) {
    if (!Number.isSafeInteger(row.id) || row.id <= 0 || row.id === deps.selfId || row.id === deps.peer.id || row.isBot) continue;
    if (!selectedById.has(row.id)) selectedById.set(row.id, row);
    if (selectedById.size >= 3) break;
  }
  const selected = [...selectedById.values()];

  let chatId: number;
  let inviteUserIds: number[];
  if (selected.length === 0) {
    const dialog = await deps.api.post<{ id: number; kind?: string }>("/v1/chats/dialog", { user_id: deps.peer.id });
    if (!Number.isSafeInteger(dialog.id) || dialog.id <= 0 || (dialog.kind !== undefined && dialog.kind !== "dialog")) {
      throw new Error("invalid promoted dialog");
    }
    chatId = dialog.id;
    inviteUserIds = [deps.peer.id];
  } else {
    const memberIds = [deps.peer.id, ...selected.map((row) => row.id)];
    const names = [
      deps.peer.name,
      ...selected.map((row) => row.alias?.trim() || row.name.trim() || row.username || String(row.id)),
    ];
    const prefix = deps.locale.toLowerCase().startsWith("ru") ? "Звонок: " : "Call: ";
    const group = await deps.api.post<{ id: number }>("/v1/chats/group", {
      title: `${prefix}${names.join(", ")}`.slice(0, 120),
      about: "",
      member_ids: memberIds,
    });
    if (!Number.isSafeInteger(group.id) || group.id <= 0) throw new Error("invalid promoted group");
    chatId = group.id;
    const roster = await deps.api.get<Array<{ id: number; is_bot?: boolean }>>(
      `/v1/chats/${encodeURIComponent(String(chatId))}/members?limit=50`,
    );
    inviteUserIds = [...new Set(roster
      .filter((member) => Number.isSafeInteger(member.id) && member.id > 0 && member.id !== deps.selfId && member.is_bot !== true)
      .map((member) => member.id))].slice(0, 4);
    if (!inviteUserIds.includes(deps.peer.id)) throw new Error("peer could not be added to the group call");
  }

  const room = await deps.api.post<{ id: string }>(`/v1/chats/${encodeURIComponent(String(chatId))}/conference`, {
    mode: "conversation",
    video: deps.video,
  });
  if (typeof room.id !== "string" || !room.id.trim()) throw new Error("invalid promoted conference");
  return { chatId, conferenceId: room.id.trim(), inviteUserIds };
}
